                            PRIMARY KEY (`id`) USING BTREE,
                            UNIQUE INDEX `ID_362432102577400`(`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '证书管理' ROW_FORMAT = Dynamic;

