                                      `contact` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人',
                                      `contact_id` bigint(20) NULL DEFAULT NULL COMMENT '联系人ID',
                                      `contact_number` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
                                      `cat_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类目编码',
                                      `description` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述',
                                      `system_job_id` bigint(20) NULL DEFAULT NULL COMMENT '定时任务调度表id',
                                      `last_execute_time` datetime NULL DEFAULT NULL COMMENT '最后执行时间',
                                      `valid_flag` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1' COMMENT '是否有效;0：无效，1：有效',
                                      `del_flag` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志;1：已删除，0：未删除',
                                      `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
                                      `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                                      `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
                                      `update_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
                                      `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                                      `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
                                      `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
                                      `last_table_count` int(11) NULL DEFAULT 0 COMMENT '上次变化表数',
                                      `email` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮箱',
                                      `node_id` bigint(20) NOT NULL COMMENT '节点id;DolphinScheduler中的节点id',
                                      `node_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '节点编码;DolphinScheduler中的节点编码',
                                      `task_id` bigint(20) NOT NULL COMMENT '任务id;DolphinScheduler中的任务id',
                                      `task_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务编码;DolphinScheduler中的任务编码',
                                      PRIMARY KEY (`id`) USING BTREE,
                                      UNIQUE INDEX `ID_362181557852200`(`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '数据发现任务' ROW_FORMAT = Dynamic;

