INSERT INTO `att_clean_rule` VALUES (23, '字段值首字母大写', '1', '将字段中的每个单词首字母大写，其余转为小写', '0', '0', '千桐科技', 1, '2025-08-11 14:49:00', '千桐科技', 1, '2025-08-11 17:13:30', NULL, '“beijing city” → “Beijing City”', '31', '将字段中的每个单词首字母大写，其余转为小写', NULL, '023', 'A03A02');
INSERT INTO `att_clean_rule` VALUES (24, '枚举值映射标准化', '1', '将字段值根据配置字典进行映射替换，确保值域统一', '1', '0', '千桐科技', 1, '2025-08-11 14:49:19', '千桐科技', 1, '2025-08-11 17:21:12', NULL, '“1” → “启用”；“0” → “停用”', '32', '将字段值根据配置字典进行映射替换，确保值域统一', 'MENU_CUSTOM', '024', 'A03A03');
INSERT INTO `att_clean_rule` VALUES (25, '按主键去重（保留首条）', '1', '按指定唯一标识字段对记录去重，仅保留首条出现的数据，适用于无时间戳场景', '0', '0', '千桐科技', 1, '2025-08-11 14:49:41', '千桐科技', 1, '2025-08-11 17:13:18', NULL, '按“客户ID”去重，保留最先出现的记录', '39', '按指定唯一标识字段对记录去重，仅保留首条出现的数据，适用于无时间戳场景', NULL, '025', 'A04A01');
INSERT INTO `att_clean_rule` VALUES (26, '按主键去重（按时间字段保留最新）', '1', '配置时间字段，在重复记录中仅保留时间最新的一条', '0', '0', '千桐科技', 1, '2025-08-11 14:49:57', '千桐科技', 1, '2025-08-11 17:13:14', NULL, '按“订单编号”去重，保留“更新时间”最大的一条记录', '39', '配置时间字段，在重复记录中仅保留时间最新的一条', NULL, '026', 'A04A01');
INSERT INTO `att_clean_rule` VALUES (27, '按优先级字段保留记录', '1', '当记录存在多个来源或等级标记时，按照优先级高的记录进行保留', '0', '0', '千桐科技', 1, '2025-08-11 14:50:15', '千桐科技', 1, '2025-08-11 17:13:09', NULL, '“数据来源”为“系统录入”优先于“Excel导入”，如果多条都是“系统录入”则应用最新一条', '39', '当记录存在多个来源或等级标记时，按照优先级高的记录进行保留', NULL, '027', 'A04A01');
INSERT INTO `att_clean_rule` VALUES (28, '按非空字段优先保留记录', '1', '当关键字段存在空值时，优先保留值完整的记录', '0', '0', '千桐科技', 1, '2025-08-11 14:50:33', '千桐科技', 1, '2025-08-11 17:13:05', NULL, '两条重复记录中一条手机号为空 → 保留手机号不为空的那条', '39', '当关键字段存在空值时，优先保留值完整的记录', NULL, '028', 'A04A01');
INSERT INTO `att_clean_rule` VALUES (29, '按组合字段去重（保留最新或首条）', '1', '指定多个字段作为联合唯一键，对重复记录进行去重，可配置保留策略（首条、最新）', '1', '0', '千桐科技', 1, '2025-08-11 14:50:50', '千桐科技', 1, '2025-08-11 17:21:19', NULL, '按“用户ID + 年份”去重，保留“更新时间”最大的一条记录', '39', '指定多个字段作为联合唯一键，对重复记录进行去重，可配置保留策略（首条、最新）', 'KEEP_LATEST_OR_FIRST', '029', 'A04A01');
INSERT INTO `att_clean_rule` VALUES (30, '替换无效数值', '1', '将不在合法范围内的数值字段替换为指定默认值（如负数、过大值、异常标识值）', '0', '0', '千桐科技', 1, '2025-08-11 14:51:21', '千桐科技', 1, '2025-08-11 17:12:24', NULL, '年龄字段为 -1 或 999 → 替换为 null 或 0', '46', '将不在合法范围内的数值字段替换为指定默认值（如负数、过大值、异常标识值）', NULL, '030', 'A05A01');
INSERT INTO `att_clean_rule` VALUES (31, '替换非法枚举值', '1', '当字段值不在指定值域集合中时，替换为默认值或空值', '0', '0', '千桐科技', 1, '2025-08-11 14:51:37', '千桐科技', 1, '2025-08-11 17:12:10', NULL, '状态字段值为“异常值99” → 替换为“未知”', '46', '当字段值不在指定值域集合中时，替换为默认值或空值', NULL, '031', 'A05A01');
INSERT INTO `att_clean_rule` VALUES (32, '替换无效时间格式', '1', '当字段值不符合日期时间标准格式时，替换为默认时间或空值', '0', '0', '千桐科技', 1, '2025-08-11 14:51:54', '千桐科技', 1, '2025-08-11 17:12:05', NULL, '“32/13/2023” → 替换为 null 或“1970-01-01”', '46', '当字段值不符合日期时间标准格式时，替换为默认时间或空值', NULL, '032', 'A05A01');
INSERT INTO `att_clean_rule` VALUES (33, '替换非法布尔值', '1', '将字段中不符合布尔定义的值替换为默认布尔值', '0', '0', '千桐科技', 1, '2025-08-11 14:52:10', '千桐科技', 1, '2025-08-11 17:12:01', NULL, '“abc” → 替换为 false', '46', '将字段中不符合布尔定义的值替换为默认布尔值', NULL, '033', 'A05A01');
INSERT INTO `att_clean_rule` VALUES (34, '关键词脱敏', '1', '将字段值中包含的敏感词进行掩码处理，支持配置脱敏字符', '0', '0', '千桐科技', 1, '2025-08-11 14:52:32', '千桐科技', 1, '2025-08-11 17:11:57', NULL, '“这是一条涉黄内容” → “这是一条***内容”', '47', '将字段值中包含的敏感词进行掩码处理，支持配置脱敏字符', NULL, '034', 'A05A02');
INSERT INTO `att_clean_rule` VALUES (35, '敏感词替换', '1', '将命中词表中的敏感词替换为指定文本（如“未知”、“违规内容”）', '0', '0', '千桐科技', 1, '2025-08-11 14:52:48', '千桐科技', 1, '2025-08-11 17:11:53', NULL, '“暴恐言论” → 替换为“违规内容”', '47', '将命中词表中的敏感词替换为指定文本（如“未知”、“违规内容”）', NULL, '035', 'A05A02');
INSERT INTO `att_clean_rule` VALUES (36, '修正未来时间值', '1', '当时间字段值晚于当前时间时，自动修正为当前时间或指定边界值', '0', '0', '千桐科技', 1, '2025-08-11 14:53:11', '千桐科技', 1, '2025-08-11 17:11:48', NULL, '注册时间为“2099-12-31” → 替换为“当前系统时间”', '55', '当时间字段值晚于当前时间时，自动修正为当前时间或指定边界值', NULL, '036', 'A06A01');
INSERT INTO `att_clean_rule` VALUES (37, '校正超前时间差值', '1', '当字段时间超过当前时间指定间隔（如7天）时，进行修正处理', '0', '0', '千桐科技', 1, '2025-08-11 14:53:27', '千桐科技', 1, '2025-08-11 17:11:43', NULL, '预约时间为当前时间+15天 → 替换为“当前时间+7天”', '55', '当字段时间超过当前时间指定间隔（如7天）时，进行修正处理', NULL, '037', 'A06A01');
INSERT INTO `att_clean_rule` VALUES (38, '填补空时间为当前时间', '1', '当时间字段为空时，填充为系统当前时间或默认时间', '0', '0', '千桐科技', 1, '2025-08-11 14:53:44', '千桐科技', 1, '2025-08-11 17:11:38', NULL, '更新时间字段为 null → 替换为“2025-07-18 10:00:00”', '56', '当时间字段为空时，填充为系统当前时间或默认时间', NULL, '038', 'A06A02');
INSERT INTO `att_clean_rule` VALUES (39, '清理过期记录', '1', '当记录中的时间字段早于当前时间指定阈值时（如30天），标记或删除', '1', '0', '千桐科技', 1, '2025-08-11 14:54:01', '千桐科技', 1, '2025-08-11 17:22:24', NULL, '最后登录时间早于30天前 → 该用户记录设为“过期”', '57', '当记录中的时间字段早于当前时间指定阈值时（如30天），标记或删除', 'CHECK_EXPIRATION', '039', 'A06A03');
INSERT INTO `att_clean_rule` VALUES (40, '修正历史时间边界', '1', '当字段值早于系统可接受最早时间时，替换为指定边界值', '0', '0', '千桐科技', 1, '2025-08-11 14:54:16', '千桐科技', 1, '2025-08-11 17:10:19', NULL, '创建时间为“1900-01-01” → 替换为“2000-01-01”', '57', '当字段值早于系统可接受最早时间时，替换为指定边界值', NULL, '040', 'A06A03');
INSERT INTO `att_client` VALUES (1, '省级水资源监控系统', '0', '366c29e472774d368876144123b19b2c', NULL, NULL, NULL, '/profile/2025/09/30/68db939de4b0cf461aafd3a3.png', '作为上级业务平台，数据中台向该系统主动推送加工后的取水量分析结果、计划执行率等数据，用于其监管展示与预警。', '1', '1', '0', '吴同', 2, '2025-09-18 15:25:51', '吴同', 2, '2025-09-30 16:23:58', NULL);
