INSERT INTO `att_client` VALUES (5, '灌区信息化系统', '0', '53ef84d0d89a4a6c8c03412c2f769438', NULL, NULL, NULL, '/profile/2025/09/18/68cbb45de4b0649f2379b125.png', '作为同级平台，其运行数据需接入中台，由中台完成数据汇聚、清洗与整合治理，形成农业用水统一视图。', '1', '1', '0', '吴同', 2, '2025-09-18 15:27:27', '吴同', 2, '2025-09-18 15:27:27', NULL);
