INSERT INTO `att_quality_cat` VALUES (3, '水资源管理', 2, 0, 'A01A01', '聚焦水资源的规划、配置与使用全过程数据，用于监控取用水、水量分配、用水效率等核心数据的完整性与合规性，支撑水资源总量与强度双控管理。', '1', '0', '吴同', 2, '2025-09-18 16:09:55', '吴同', 2, '2025-09-18 16:09:55', NULL);
INSERT INTO `att_quality_cat` VALUES (4, '水雨情监测	', 2, 0, 'A01A02', '面向雨量、水位、流量等实时监测数据的质量管理，重点保障数据采集完整性、上报及时性和异常值控制，为防汛抗旱提供可靠数据支撑。', '1', '0', '吴同', 2, '2025-09-18 16:10:58', '吴同', 2, '2025-09-18 16:10:58', NULL);
INSERT INTO `att_quality_cat` VALUES (5, '防洪减灾管理', 2, 0, 'A01A03', '管理洪水预警、风险点、灾情上报、应急响应等数据质量，确保关键信息完整、准确、可追溯，提升应急指挥决策的数据可信度。', '1', '0', '吴同', 2, '2025-09-18 16:11:10', '吴同', 2, '2025-09-18 16:11:10', NULL);
INSERT INTO `att_quality_cat` VALUES (6, '水资源调度	', 2, 0, 'A01A04', '针对调度计划、指令执行、工程运行等调度过程数据的质量管控，保障调度数据的时效性、逻辑合理性和过程留痕完整性。', '1', '0', '吴同', 2, '2025-09-18 16:11:17', '吴同', 2, '2025-09-18 16:11:17', NULL);
INSERT INTO `att_quality_cat` VALUES (7, '农村水利管理	', 2, 0, 'A01A05', '涵盖农村供水、灌区、小型水利设施等基础台账与运行数据，重点提升农村水利数据的覆盖度、更新及时性和服务人口匹配准确性。', '1', '0', '吴同', 2, '2025-09-18 16:11:25', '吴同', 2, '2025-09-18 16:11:25', NULL);
INSERT INTO `att_quality_cat` VALUES (8, '河湖管理与保护', 2, 0, 'A01A06', '管理河湖名录、巡河记录、“四乱”问题、健康评价等数据，确保河湖监管数据的动态更新、空间一致性和问题闭环管理。', '1', '0', '吴同', 2, '2025-09-18 16:11:32', '吴同', 2, '2025-09-18 16:11:32', NULL);
