INSERT INTO `att_theme` VALUES (1, '默认主题', NULL, 0, NULL, '1', '1', '吴大同', 1, '2025-09-16 17:34:31', '吴大同', 1, '2025-09-16 17:34:31', NULL);
INSERT INTO `att_theme` VALUES (2, '水资源管理', NULL, 1, '聚焦区域水资源总量、水质状况、取用水行为等核心数据，涵盖地表水、地下水、非常规水源的监测与管理信息。通过统一归集与治理，支撑水资源承载能力评估、用水总量控制及可持续利用决策。', '1', '0', '吴同', 2, '2025-09-18 15:18:15', '吴同', 2, '2025-09-18 15:18:22', NULL);
INSERT INTO `att_theme` VALUES (3, '水雨情监测	', NULL, 2, '整合降水、水位、流量、流速等实时监测数据，覆盖雨量站、水文站、河道断面等感知节点。实现对流域内水情动态的全面掌握，为洪水预警、调度响应和应急指挥提供及时准确的数据支持。', '1', '0', '吴同', 2, '2025-09-18 15:18:44', '吴同', 2, '2025-09-18 15:18:44', NULL);
INSERT INTO `att_theme` VALUES (4, '防洪减灾管理', NULL, 3, '汇聚防洪预案、险情上报、应急响应、物资储备、转移安置等全过程管理数据，构建从风险识别到灾后评估的完整数据链条。支撑防汛指挥体系高效运转，提升灾害应对与风险防控能力。', '1', '0', '吴同', 2, '2025-09-18 15:18:54', '吴同', 2, '2025-09-18 15:18:54', NULL);
INSERT INTO `att_theme` VALUES (5, '水资源调度	', '/profile/2025/09/18/68cbb41fe4b0649f2379b121.png', 4, '管理跨区域、多水源的水量调度方案、调度指令、执行过程及效果反馈数据，涵盖水库、闸坝、泵站等关键工程调度行为。通过数据驱动优化配置流程，保障供水安全与生态需水。', '1', '0', '吴同', 2, '2025-09-18 15:21:05', '吴同', 2, '2025-09-18 15:26:25', NULL);
INSERT INTO `att_theme` VALUES (6, '农村水利管理	', '/profile/2025/09/18/68cbb42ae4b0649f2379b122.png', 5, '聚焦农村饮水安全、灌区运行、小型水利工程（如塘坝、机井）等管理数据，覆盖建设、运维、服务全生命周期。支撑农村水利精细化管理和乡村振兴战略实施。', '1', '0', '吴同', 2, '2025-09-18 15:24:02', '吴同', 2, '2025-09-18 15:26:36', NULL);
INSERT INTO `att_theme` VALUES (7, '河湖管理与保护', '/profile/2025/09/18/68cbb42fe4b0649f2379b123.png', 6, '整合河湖基础信息、水域岸线、排污口、涉水活动、河长巡河记录等数据，支撑河湖“四乱”治理、生态保护与长效监管。服务于河湖健康评价与生态文明建设。', '1', '0', '吴同', 2, '2025-09-18 15:24:17', '吴同', 2, '2025-09-18 15:26:40', NULL);
INSERT INTO `att_theme` VALUES (8, '水文监测与情报', '/profile/2025/09/18/68cbb433e4b0649f2379b124.png', 7, '负责水文要素的自动化采集、整编处理、质量控制与情报生成，包括水位、流量、泥沙、蒸发、水质等专业观测数据。作为水利基础数据底座，为各业务系统提供权威、可靠的水文信息服务。', '1', '0', '吴同', 2, '2025-09-18 15:24:28', '吴同', 2, '2025-09-18 15:26:45', NULL);
