INSERT INTO `da_datasource` VALUES (1, '数据中台原始库', 'DM8', '{\"username\":\"ods\",\"password\":\"lmOxx+3wDu3oUMxRKAR3LQ==\",\"dbname\":\"ods\"}', 'dm8-demo', 5236, 0, 0, 0, '存放未经过处理的原始数据至数据仓库系统，结构上与源系统保持一致', '1', '吴同', 2, '2025-09-19 14:31:41', '吴同', 2, '2025-09-30 14:08:24', NULL, '0');
INSERT INTO `da_datasource` VALUES (2, '数据中台数据明细库', 'DM8', '{\"username\":\"dwd\",\"password\":\"lmOxx+3wDu3oUMxRKAR3LQ==\",\"dbname\":\"dwd\"}', 'dm8-demo', 5236, 0, 0, 0, '以业务过程作为建模驱动，基于每个具体的业务过程特点，构建最细粒度的明细层事实表。', '1', '吴同', 2, '2025-09-19 15:53:44', '吴同', 2, '2025-09-30 14:09:05', NULL, '0');
