INSERT INTO `dpp_etl_node` VALUES (120, '3', 'SPARK', 'SparkSQL_水位日统计报表', '152726374059328', 2, 1, '152317790975712', '{\"taskPriority\":\"MEDIUM\",\"workerGroup\":\"default\",\"failRetryTimes\":0,\"failRetryInterval\":1,\"delayTime\":0,\"jobManagerMemory\":\"1G\",\"taskManagerMemory\":\"2G\",\"slot\":1,\"taskManager\":2,\"parallelism\":1,\"yarnQueue\":\"\",\"driverCores\":1,\"driverMemory\":\"512M\",\"numExecutors\":1,\"executorMemory\":\"1G\",\"executorCores\":1,\"typaCode\":\"SparkSql\",\"datasourceId\":\"\",\"sqlType\":\"0\",\"taskType\":\"SPARK\",\"segm\":\"\",\"componentType\":\"53\",\"localParams\":[],\"executeMode\":\"\",\"sql\":\"-- 建议：控制并行度（按你的集群修改）\\r\\nSET spark.sql.shuffle.partitions=4;\\r\\n\\r\\n-- 1) 源表（MySQL）注册为临时视图\\r\\nCREATE TEMPORARY VIEW hyd_water_level_src\\r\\nUSING jdbc\\r\\nOPTIONS (\\r\\n  url \'jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai\',\\r\\n  dbtable \'hyd_water_level\',\\r\\n  user \'root\',\\r\\n  password \'sfdjfFF#s2332\',\\r\\n  driver \'com.mysql.cj.jdbc.Driver\'\\r\\n);\\r\\n\\r\\n-- 2) 目标表（MySQL）作为可写的数据源表（映射到已存在的 hyd_water_level_spark）\\r\\n--    注意：这里不会在 MySQL 里建表，只是把这个 JDBC 映射成 Spark SQL 的一张可写表\\r\\nCREATE TABLE IF NOT EXISTS hyd_water_level_spark_jdbc\\r\\nUSING jdbc\\r\\nOPTIONS (\\r\\n  url \'jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai\',\\r\\n  dbtable \'hyd_water_level_spark\',\\r\\n  user \'root\',\\r\\n  password \'sfdjfFF#s2332\',\\r\\n  driver \'com.mysql.cj.jdbc.Driver\'\\r\\n);\\r\\n\\r\\n-- 3) 全量复制（保留 id）\\r\\nINSERT INTO hyd_water_level_spark_jdbc\\r\\nSELECT\\r\\n  id,\\r\\n  station_code,\\r\\n  sensor_id,\\r\\n  obs_time,\\r\\n  obs_date,\\r\\n  water_level_m,\\r\\n  quality_code,\\r\\n  source,\\r\\n  trace_id,\\r\\n  ext_json,\\r\\n  created_at\\r\\nFROM hyd_water_level_src;\\r\\n\"}', 'MEDIUM', 0, 1, 0, 0, -1, -1, '【离线计算】查询水位实时数据，生成每日统计报表', 100, '1', '0', '吴同', 2, '2025-09-23 09:09:26', '吴同', 2, '2025-09-23 09:09:26', NULL, '53');
INSERT INTO `dpp_etl_node` VALUES (121, '1', 'SPARK', '转换组件', '153382392548896', 1, 1, '152317790975712', '{\"mainArgs\":{},\"tableFields\":[{\"name\":\"根据id和编码去重\",\"ruleName\":\"按组合字段去重（保留最新或首条）\",\"ruleCode\":\"029\",\"status\":\"1\",\"whereClause\":\"\",\"columns\":[\"STATION_ID\",\"STATION_CODE\"],\"tableName\":\"\",\"ruleDesc\":\"\",\"type\":\"39\",\"ruleConfig\":\"{\\\"columns\\\":[\\\"STATION_ID\\\",\\\"STATION_CODE\\\"],\\\"stringValue\\\":[{\\\"sort\\\":1,\\\"columns\\\":\\\"STATION_ID\\\",\\\"type\\\":\\\"0\\\"}],\\\"handleType\\\":\\\"1\\\",\\\"parentName\\\":\\\"重复记录删除类\\\"}\",\"id\":\"\",\"ruleType\":\"KEEP_LATEST_OR_FIRST\",\"parentName\":\"重复记录删除类\"}],\"typeName\":\"转换组件\",\"icon\":\"data:image/svg+xml;base64,\",\"type\":3,\"parentId\":\"\",\"inputFields\":[{\"columnName\":\"STATION_ID\",\"columnComment\":\"站点主键（源）\",\"columnType\":\"NUMBER\",\"columnLength\":22,\"columnScale\":0,\"nullableFlag\":\"1\",\"pkFlag\":\"1\",\"source\":\"表输入组件\"},{\"columnName\":\"STATION_CODE\",\"columnComment\":\"站点编码（跨源统一关联键）\",\"columnType\":\"VARCHAR2\",\"columnLength\":64,\"columnScale\":0,\"nullableFlag\":\"1\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"STATION_NAME\",\"columnComment\":\"站点名称\",\"columnType\":\"VARCHAR2\",\"columnLength\":200,\"columnScale\":0,\"nullableFlag\":\"1\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"BASIN_CODE\",\"columnComment\":\"流域编码\",\"columnType\":\"VARCHAR2\",\"columnLength\":64,\"columnScale\":0,\"nullableFlag\":\"0\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"RIVER_NAME\",\"columnComment\":\"河流名称\",\"columnType\":\"VARCHAR2\",\"columnLength\":128,\"columnScale\":0,\"nullableFlag\":\"0\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"LONGITUDE\",\"columnComment\":\"经度\",\"columnType\":\"DECIMAL\",\"columnLength\":22,\"columnScale\":6,\"nullableFlag\":\"0\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"LATITUDE\",\"columnComment\":\"纬度\",\"columnType\":\"DECIMAL\",\"columnLength\":22,\"columnScale\":6,\"nullableFlag\":\"0\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"ADMIN_REGION_CODE\",\"columnComment\":\"行政区划码\",\"columnType\":\"VARCHAR2\",\"columnLength\":12,\"columnScale\":0,\"nullableFlag\":\"0\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"STATUS\",\"columnComment\":\"1启用/0停用\",\"columnType\":\"NUMBER\",\"columnLength\":22,\"columnScale\":0,\"nullableFlag\":\"1\",\"pkFlag\":\"0\",\"defaultValue\":\"1\",\"source\":\"表输入组件\"},{\"columnName\":\"CREATED_AT\",\"columnComment\":\"创建时间\",\"columnType\":\"TIMESTAMP\",\"columnLength\":8,\"columnScale\":0,\"nullableFlag\":\"1\",\"pkFlag\":\"0\",\"defaultValue\":\"CURRENT_TIMESTAMP\",\"source\":\"表输入组件\"},{\"columnName\":\"UPDATED_AT\",\"columnComment\":\"修改时间\",\"columnType\":\"TIMESTAMP\",\"columnLength\":8,\"columnScale\":0,\"nullableFlag\":\"1\",\"pkFlag\":\"0\",\"defaultValue\":\"CURRENT_TIMESTAMP\",\"source\":\"表输入组件\"}],\"outputFields\":[{\"columnName\":\"STATION_ID\",\"columnComment\":\"站点主键（源）\",\"columnType\":\"NUMBER\",\"columnLength\":19,\"columnScale\":0,\"nullableFlag\":\"1\",\"pkFlag\":\"1\",\"source\":\"表输入组件\"},{\"columnName\":\"STATION_CODE\",\"columnComment\":\"站点编码（跨源统一关联键）\",\"columnType\":\"VARCHAR2\",\"columnLength\":64,\"columnScale\":0,\"nullableFlag\":\"1\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"STATION_NAME\",\"columnComment\":\"站点名称\",\"columnType\":\"VARCHAR2\",\"columnLength\":200,\"columnScale\":0,\"nullableFlag\":\"1\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"BASIN_CODE\",\"columnComment\":\"流域编码\",\"columnType\":\"VARCHAR2\",\"columnLength\":64,\"columnScale\":0,\"nullableFlag\":\"0\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"RIVER_NAME\",\"columnComment\":\"河流名称\",\"columnType\":\"VARCHAR2\",\"columnLength\":128,\"columnScale\":0,\"nullableFlag\":\"0\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"LONGITUDE\",\"columnComment\":\"经度\",\"columnType\":\"DECIMAL\",\"columnLength\":10,\"columnScale\":6,\"nullableFlag\":\"0\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"LATITUDE\",\"columnComment\":\"纬度\",\"columnType\":\"DECIMAL\",\"columnLength\":10,\"columnScale\":6,\"nullableFlag\":\"0\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"ADMIN_REGION_CODE\",\"columnComment\":\"行政区划码\",\"columnType\":\"VARCHAR2\",\"columnLength\":12,\"columnScale\":0,\"nullableFlag\":\"0\",\"pkFlag\":\"0\",\"source\":\"表输入组件\"},{\"columnName\":\"STATUS\",\"columnComment\":\"1启用/0停用\",\"columnType\":\"NUMBER\",\"columnLength\":1,\"columnScale\":0,\"nullableFlag\":\"1\",\"pkFlag\":\"0\",\"defaultValue\":\"1\",\"source\":\"表输入组件\"},{\"columnName\":\"CREATED_AT\",\"columnComment\":\"创建时间\",\"columnType\":\"TIMESTAMP\",\"columnLength\":8,\"columnScale\":0,\"nullableFlag\":\"1\",\"pkFlag\":\"0\",\"defaultValue\":\"CURRENT_TIMESTAMP\",\"source\":\"表输入组件\"},{\"columnName\":\"UPDATED_AT\",\"columnComment\":\"修改时间\",\"columnType\":\"TIMESTAMP\",\"columnLength\":8,\"columnScale\":0,\"nullableFlag\":\"1\",\"pkFlag\":\"0\",\"defaultValue\":\"CURRENT_TIMESTAMP\",\"source\":\"表输入组件\"}],\"taskType\":\"SPARK\",\"datasourceId\":\"\",\"where\":\"\",\"batchSize\":\"1024\",\"config\":\"\"}', 'MEDIUM', 0, 1, 0, 0, -1, -1, NULL, NULL, '1', '0', '吴同', 2, '2025-09-30 15:43:52', '吴同', 2, '2025-09-30 15:43:52', NULL, '31');
INSERT INTO `dpp_etl_node` VALUES (123, '3', 'SQL', 'Kingbase_水位日统计', '153383838261792', 2, 1, '152317790975712', '{\"taskPriority\":\"MEDIUM\",\"workerGroup\":\"default\",\"failRetryTimes\":0,\"failRetryInterval\":1,\"delayTime\":1,\"jobManagerMemory\":\"1G\",\"taskManagerMemory\":\"2G\",\"slot\":1,\"taskManager\":2,\"parallelism\":1,\"yarnQueue\":\"\",\"driverCores\":1,\"driverMemory\":\"512M\",\"numExecutors\":1,\"executorMemory\":\"1G\",\"executorCores\":1,\"typaCode\":\"Kingbase\",\"datasourceId\":5,\"sqlType\":\"0\",\"taskType\":\"SQL\",\"segm\":\"\",\"componentType\":\"51\",\"localParams\":[],\"sql\":\"/* ===========================================================\\r\\n   环境准备（按需修改库名）\\r\\n   =========================================================== */\\r\\n-- 可选：使用你的业务库\\r\\nCREATE DATABASE IF NOT EXISTS hydrology DEFAULT CHARACTER SET utf8mb4;\\r\\nUSE hydrology;\\r\\n\\r\\n/* ===========================================================\\r\\n   1) 报表表（日平均水位）\\r\\n   - 以 (station_code, stat_date) 做唯一键，兼容无维表场景\\r\\n   - 如存在维表，会同步写入 station_id / station_name\\r\\n   =========================================================== */\\r\\nCREATE TABLE IF NOT EXISTS dws_station_water_day_report (\\r\\n  station_code   VARCHAR(64)  NOT NULL COMMENT \'测站编码\',\\r\\n  station_id     BIGINT                COMMENT \'测站ID（有维表时填充）\',\\r\\n  station_name   VARCHAR(128)          COMMENT \'测站名称（有维表时填充；无维表时=station_code）\',\\r\\n  avg_level_day  DECIMAL(10,3)         COMMENT \'日平均水位(米)\',\\r\\n  stat_date      DATE         NOT NULL COMMENT \'统计日期\',\\r\\n  PRIMARY KEY (station_code, stat_date),\\r\\n  KEY idx_stat_date (stat_date),\\r\\n  KEY idx_station_id (station_id)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'站点水位日统计（日均）\';\\r\\n\\r\\n/* ===========================================================\\r\\n   2) 单日报表过程\\r\\n   - 输入：p_stat_date（统计yyyy-MM-dd）\\r\\n   - 逻辑：\\r\\n       取 obs_date，否则取 DATE(obs_time) 作为统计日期\\r\\n       按 (station_code, stat_date) 聚合 AVG(water_level_m)\\r\\n       LEFT JOIN hyd_station（如存在）填充 id/name\\r\\n       用 ON DUPLICATE KEY 做 upsert\\r\\n   =========================================================== */\\r\\nDELIMITER $$\\r\\n\\r\\nDROP PROCEDURE IF EXISTS prc_gen_water_day_report $$\\r\\nCREATE PROCEDURE prc_gen_water_day_report(IN p_stat_date DATE)\\r\\nBEGIN\\r\\n  /*\\r\\n    说明：\\r\\n    - 若不存在 hyd_station 表，LEFT JOIN 返回 NULL，不影响执行；\\r\\n      station_id 将为 NULL，station_name 用 station_code 兜底。\\r\\n    - hyd_water_level 建议在 hydrology 库中（按需改库名前缀）。\\r\\n  */\\r\\n  INSERT INTO dws_station_water_day_report\\r\\n  (\\r\\n    station_code, station_id, station_name, avg_level_day, stat_date\\r\\n  )\\r\\n  SELECT\\r\\n    wl.station_code                                                AS station_code,\\r\\n    s.station_id                                                   AS station_id,               -- 可能为 NULL\\r\\n    COALESCE(s.station_name, wl.station_code)                      AS station_name,             -- 兜底\\r\\n    ROUND(AVG(CAST(wl.water_level_m AS DECIMAL(10,3))), 3)         AS avg_level_day,\\r\\n    p_stat_date                                                    AS stat_date\\r\\n  FROM hydrology.hyd_water_level wl\\r\\n  LEFT JOIN hydrology.hyd_station s\\r\\n    ON s.station_code = wl.station_code\\r\\n  WHERE\\r\\n      (CASE\\r\\n         WHEN wl.obs_date IS NOT NULL THEN wl.obs_date\\r\\n         ELSE DATE(wl.obs_time)\\r\\n       END) = p_stat_date\\r\\n    AND wl.water_level_m IS NOT NULL\\r\\n  GROUP BY wl.station_code, s.station_id, COALESCE(s.station_name, wl.station_code)\\r\\n  ON DUPLICATE KEY UPDATE\\r\\n      station_id     = VALUES(station_id),\\r\\n      station_name   = VALUES(station_name),\\r\\n      avg_level_day  = VALUES(avg_level_day);\\r\\nEND $$\\r\\nDELIMITER ;\\r\\n\\r\\n/* ===========================================================\\r\\n   3) 区间报表过程（含首尾）\\r\\n   =========================================================== */\\r\\nDELIMITER $$\\r\\n\\r\\nDROP PROCEDURE IF EXISTS prc_gen_water_day_report_range $$\\r\\nCREATE PROCEDURE prc_gen_water_day_report_range(IN p_begin_date DATE, IN p_end_date DATE)\\r\\nBEGIN\\r\\n  DECLARE v_day DATE;\\r\\n\\r\\n  IF p_begin_date IS NULL OR p_end_date IS NULL THEN\\r\\n    SIGNAL SQLSTATE \'45000\' SET MESSAGE_TEXT = \'起止日期不可为空\';\\r\\n  END IF;\\r\\n\\r\\n  IF p_begin_date > p_end_date THEN\\r\\n    SIGNAL SQLSTATE \'45000\' SET MESSAGE_TEXT = \'起始日期不能晚于截止日期\';\\r\\n  END IF;\\r\\n\\r\\n  SET v_day = p_begin_date;\\r\\n  WHILE v_day <= p_end_date DO\\r\\n    CALL prc_gen_water_day_report(v_day);\\r\\n    SET v_day = DATE_ADD(v_day, INTERVAL 1 DAY);\\r\\n  END WHILE;\\r\\nEND $$\\r\\nDELIMITER ;\\r\\n\\r\\n/* ===========================================================\\r\\n   4) 使用示例\\r\\n   =========================================================== */\\r\\n-- 生成某一天（例如 2025-01-01）\\r\\nCALL prc_gen_water_day_report(\'2025-01-01\');\\r\\n\\r\\n-- 生成一段时间（例如 2025-01-01 ~ 2025-01-07）\\r\\nCALL prc_gen_water_day_report_range(\'2025-01-01\', \'2025-01-07\');\\r\\n\\r\\n-- 校验\\r\\nSELECT *\\r\\nFROM dws_station_water_day_report\\r\\nORDER BY stat_date DESC, station_code\\r\\nLIMIT 20;\\r\\n\\r\\n/* ===========================================================\\r\\n   5) （可选）事件调度：每天 00:10 生成“昨日日报”\\r\\n   - 需要：SET GLOBAL event_scheduler = ON;\\r\\n   - 如不需要可删除此段\\r\\n   =========================================================== */\\r\\nSET GLOBAL event_scheduler = ON;\\r\\n\\r\\nCREATE EVENT IF NOT EXISTS evt_gen_water_day_report_yesterday\\r\\nON SCHEDULE EVERY 1 DAY\\r\\nSTARTS TIMESTAMP(CURRENT_DATE, \'00:10:00\')\\r\\nDO\\r\\n  CALL prc_gen_water_day_report(DATE_SUB(CURDATE(), INTERVAL 1 DAY));\\r\\n\",\"executeMode\":\"\",\"datasources\":{\"datasourceType\":\"Kingbase8\",\"datasourceConfig\":\"{\\\"username\\\":\\\"qdata_dev\\\",\\\"password\\\":\\\"Z/ifqkuvoCz4bVsfXZNmlw==\\\",\\\"dbname\\\":\\\"test\\\",\\\"sid\\\":\\\"qdata_dev\\\"}\",\"ip\":\"kingbase\",\"port\":54321,\"dbname\":\"test\",\"datasource_id\":5,\"datasourceId\":5}}', 'MEDIUM', 0, 1, 0, 1, -1, -1, '【Kingbase 存储过程】查询水位实时数据，生成每日统计报表  ', 108, '1', '0', '吴同', 2, '2025-09-30 16:09:14', '吴同', 2, '2025-09-30 16:09:14', NULL, '51');
INSERT INTO `dpp_etl_node_instance` VALUES (61, '3', 'Flink流_水位信息采集', 'FLINK', 42, '152659477902656', 1, 61, 'Flink流_水位信息采集-1-20250922143548086', 1, '152317790975712', '2025-09-22 14:35:48', '2025-09-22 14:35:48', '2025-09-22 14:35:55', '/tmp/dolphinscheduler/exec/process/root/152317790975712/152659477902656_1/61/61', '/opt/dolphinscheduler/logs/20250922/152659477902656/1/61/61.log', '{\"taskPriority\":\"MEDIUM\",\"workerGroup\":\"default\",\"failRetryTimes\":0,\"failRetryInterval\":1,\"delayTime\":0,\"jobManagerMemory\":\"1G\",\"taskManagerMemory\":\"2G\",\"slot\":1,\"taskManager\":2,\"parallelism\":1,\"yarnQueue\":\"\",\"driverCores\":1,\"driverMemory\":\"512M\",\"numExecutors\":1,\"executorMemory\":\"1G\",\"executorCores\":1,\"typaCode\":\"FlinkStream\",\"datasourceId\":\"\",\"sqlType\":\"0\",\"taskType\":\"FLINK\",\"segm\":\"\",\"componentType\":\"55\",\"localParams\":[],\"executeMode\":\"STREAM\",\"sql\":\"-- ========= 1) 源表：MySQL (hyd.hyd_water_level)  =========\\r\\nCREATE TABLE src_hyd_water_level (\\r\\n  id              BIGINT,              -- MySQL: bigint(20) unsigned AUTO_INCREMENT\\r\\n  station_code    STRING,\\r\\n  sensor_id       BIGINT,\\r\\n  obs_time        TIMESTAMP(3),        -- MySQL: datetime\\r\\n  obs_date        DATE,                -- MySQL: date\\r\\n  water_level_m   DECIMAL(10,3),\\r\\n  quality_code    STRING,\\r\\n  source          STRING,\\r\\n  trace_id        STRING,\\r\\n  ext_json        STRING,              -- MySQL: text -> 以 STRING 读取\\r\\n  created_at      TIMESTAMP(3),        -- MySQL: timestamp\\r\\n  PRIMARY KEY (id) NOT ENFORCED\\r\\n) WITH (\\r\\n  \'connector\' = \'mysql-cdc\',\\r\\n  \'hostname\'  = \'mysql57\',\\r\\n  \'port\'      = \'3306\',\\r\\n  \'username\'  = \'root\',\\r\\n  \'password\'  = \'sfdjfFF#s2332\',\\r\\n  \'database-name\' = \'hydrology\',\\r\\n  \'table-name\'    = \'hyd_water_level\',\\r\\n  -- 建议设置时区，避免时间字段偏移\\r\\n  \'server-time-zone\' = \'Asia/Shanghai\',\\r\\n  -- 开启增量快照，首跑更稳\\r\\n  \'scan.incremental.snapshot.enabled\' = \'true\'\\r\\n);\\r\\n\\r\\n-- ========= 2) 目标表：Doris (ods.ods_hyd_water_level_flink_stream) =========\\r\\n-- 说明：与你给的 Doris 目标表字段/顺序一致（id → created_at）\\r\\nCREATE TABLE sink_ods_hyd_water_level_flink_stream (\\r\\n  id             BIGINT         COMMENT \'自增主键\',\\r\\n  station_code   VARCHAR(64)    COMMENT \'站点编码（软关联）\',\\r\\n  sensor_id      BIGINT         COMMENT \'传感器ID（软关联）\',\\r\\n  obs_time       TIMESTAMP(3)   COMMENT \'观测时间\',          -- Doris: DATETIME，Flink 写入 TIMESTAMP(3) OK\\r\\n  obs_date       DATE           COMMENT \'观测日期\',\\r\\n  water_level_m  DECIMAL(10,3)  COMMENT \'水位(米)\',\\r\\n  quality_code   VARCHAR(16)    COMMENT \'质量代码\',\\r\\n  source         VARCHAR(64)    COMMENT \'来源\',\\r\\n  trace_id       VARCHAR(64)    COMMENT \'追踪ID/批次号\',\\r\\n  ext_json       STRING         COMMENT \'扩展字段（原 JSON）\', -- Doris TEXT 也可接收；用 STRING 写入最通用\\r\\n  created_at     TIMESTAMP(3)   COMMENT \'创建时间\'\\r\\n) WITH (\\r\\n  \'connector\' = \'doris\',\\r\\n  -- Doris FE http 端口（一般 8030）\\r\\n  \'fenodes\' = \'host.docker.internal:8030\',\\r\\n  -- JDBC URL（建议指向 9030）\\r\\n  \'jdbc-url\' = \'jdbc:mysql://host.docker.internal:9030\',\\r\\n  -- 目标库表\\r\\n  \'table.identifier\' = \'ods.ods_hyd_water_level_flink_stream\',\\r\\n  \'username\' = \'root\',\\r\\n  \'password\' = \'InC3tmU4bijT4vkl\',\\r\\n\\r\\n  -- 写入可靠性与吞吐\\r\\n  \'sink.enable-2pc\' = \'true\',\\r\\n  \'sink.label-prefix\' = \'flink_hwl\',\\r\\n  \'sink.max-retries\' = \'3\',\\r\\n  \'sink.buffer-flush.max-rows\' = \'5000\',\\r\\n  \'sink.buffer-flush.interval\' = \'5s\',\\r\\n\\r\\n  -- 建议用 JSON 格式（对 TEXT/STRING 友好）\\r\\n  \'sink.properties.format\' = \'json\',\\r\\n  \'sink.properties.read_json_by_line\' = \'true\',\\r\\n  -- 可选：严格过滤\\r\\n  \'sink.properties.max_filter_ratio\' = \'0\'\\r\\n);\\r\\n\\r\\n-- ========= 3) 实时同步（Upsert 语义由 CDC + Doris Sink 保证） =========\\r\\nINSERT INTO sink_ods_hyd_water_level_flink_stream\\r\\nSELECT\\r\\n  id,\\r\\n  CAST(station_code AS VARCHAR(64))         AS station_code,\\r\\n  sensor_id,\\r\\n  obs_time,\\r\\n  obs_date,\\r\\n  water_level_m,\\r\\n  CAST(quality_code AS VARCHAR(16))         AS quality_code,\\r\\n  CAST(source AS VARCHAR(64))               AS source,\\r\\n  CAST(trace_id AS VARCHAR(64))             AS trace_id,\\r\\n  ext_json,                                 -- 保持原样（STRING）\\r\\n  created_at\\r\\nFROM src_hyd_water_level;\"}', '2', 0, 1, 0, -1, -1, '7', 61, 61, '1', '0', NULL, NULL, '2025-09-22 14:35:48', NULL, NULL, '2025-09-22 14:35:57', NULL, '55');
