INSERT INTO `dpp_etl_node_instance_log` VALUES (153383055310496, '2025-09-30 15:49:14', '1', 145, '152655426232640', 153383052408480, '2025-09-30 15:48:59.991 - *********************************  Initialize task context  ***********************************\n2025-09-30 15:49:00.004 - 开始数据库输入节点\n2025-09-30 15:49:00.015 - 开始任务时间: 2025-09-30 15:49:00.015\n2025-09-30 15:49:00.057 - 任务参数：{\n	\"nodeName\":\"表输入组件\",\n	\"componentType\":\"1\",\n	\"projectCode\":152317790975712,\n	\"nodeCode\":\"152655426232640\",\n	\"parameter\":{\n		\"dbName\":\"WATER_TP\",\n		\"column\":[\n			\"basin_code\",\n			\"stat_month\",\n			\"station_cnt\",\n			\"avg_level\",\n			\"max_level\",\n			\"min_level\"\n		],\n		\"dbType\":\"DM8\",\n		\"readerProperty\":{\n			\"datasourceConfig\":{\n				\"username\":\"WATER_TP\",\n				\"password\":\"lmOxx+3wDu3oUMxRKAR3LQ==\",\n				\"dbname\":\"WATER_TP\"\n			},\n			\"dbName\":\"WATER_TP\",\n			\"dbType\":\"DM8\",\n			\"host\":\"dm8-demo\",\n			\"password\":\"s2LKr6LMQxVDTQx\",\n			\"port\":5236,\n			\"username\":\"WATER_TP\"\n		},\n		\"password\":\"s2LKr6LMQxVDTQx\",\n		\"dateIncrementConfig\":{\n			\"logic\":\"and\",\n			\"dateFormat\":\"yyyy-MM-dd\",\n			\"column\":[\n\n			]\n		},\n		\"idIncrementConfig\":{\n			\"incrementStart\":\"\"\n		},\n		\"datasourceId\":8,\n		\"where\":\"\",\n		\"connection\":{\n			\"querySql\":\"SELECT\\n  s.\\\"BASIN_CODE\\\"                                   AS basin_code,\\n  r.\\\"STAT_MONTH\\\"                                   AS stat_month,\\n  COUNT(DISTINCT s.\\\"STATION_ID\\\")                   AS station_cnt,     \\n  ROUND(AVG(TO_NUMBER(NULLIF(r.\\\"AVG_WATER_LEVEL\\\", \'\'))), 3) AS avg_level, \\n  ROUND(MAX(TO_NUMBER(NULLIF(r.\\\"AVG_WATER_LEVEL\\\", \'\'))), 3) AS max_level,\\n  ROUND(MIN(TO_NUMBER(NULLIF(r.\\\"AVG_WATER_LEVEL\\\", \'\'))), 3) AS min_level\\nFROM \\\"WATER_TP\\\".\\\"STATION\\\" s\\nJOIN \\\"WATER_TP\\\".\\\"STATION_WATER_MONTH_REPORT\\\" r\\n  ON r.\\\"STATION_ID\\\" = s.\\\"STATION_ID\\\"\\n-