INSERT INTO `dpp_etl_node_instance_log` VALUES (97, '2025-09-22 17:18:29', '3', 79, '152667889198400', 96, '[INFO] 2025-09-22 17:18:28.501 -\n***********************************************************************************************[INFO] 2025-09-22 17:18:28.519 - *********************************  Initialize task context  ***********************************\n[INFO] 2025-09-22 17:18:28.520 - ***********************************************************************************************\n[INFO] 2025-09-22 17:18:28.522 - Begin to initialize task\n[INFO] 2025-09-22 17:18:28.523 - Set task startTime: 1758532708523\n[INFO] 2025-09-22 17:18:28.524 - Set task appId: 96_97\n[INFO] 2025-09-22 17:18:28.527 - End initialize task {\n  \"taskInstanceId\" : 97,\n  \"taskName\" : \"SparkSQL_水位日统计报表\",\n  \"firstSubmitTime\" : 1758532708475,\n  \"startTime\" : 1758532708523,\n  \"taskType\" : \"SPARK\",\n  \"workflowInstanceHost\" : \"172.28.0.11:5678\",\n  \"host\" : \"172.28.0.17:1234\",\n  \"logPath\" : \"/opt/dolphinscheduler/logs/20250922/152667889198400/3/96/97.log\",\n  \"processId\" : 0,\n  \"processDefineCode\" : 152667889198400,\n  \"processDefineVersion\" : 3,\n  \"processInstanceId\" : 96,\n  \"scheduleTime\" : 0,\n  \"executorId\" : 1,\n  \"cmdTypeIfComplement\" : 0,\n  \"tenantCode\" : \"default\",\n  \"processDefineId\" : 0,\n  \"projectId\" : 0,\n  \"projectCode\" : 152317790975712,\n  \"taskParams\" : \"{\\\"localParams\\\":[],\\\"rawScript\\\":\\\"-- ========== 1) 源：MySQL 水位明细 ==========\\\\r\\\\nCREATE TEMPORARY VIEW hyd_water_level_src\\\\r\\\\nUSING jdbc\\\\r\\\\nOPTIONS (\\\\r\\\\n  url \'jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai\',\\\\r\\\\n  dbtable \'hyd_water_level\',\\\\r\\\\n  user \'root\',\\\\r\\\\n  password \'sfdjfFF#s2332\',\\\\r\\\\n  driver \'com.mysql.cj.jdbc.Driver\'\\\\r\\\\n);\\\\r\\\\n\\\\r\\\\n-- ========== 2) 可选维度：站点表（如没有可保留，后续会自动降级为用 station_code 代替名称）==========\\\\r\\\\n-- 期望列：station_id BIGINT, station_code VARCHAR, station_name VARCHAR\\\\r\\\\nCREATE TEMPORARY VIEW hyd_station_dim\\\\r\\\\nUSING jdbc\\\\r\\\\nOPTIONS (\\\\r\\\\n  url \'jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai\',\\\\r\\\\n  dbtable \'hyd_station\',                       -- 没有就保持这样；后续 LEFT JOIN + COALESCE 兼容\\\\r\\\\n  user \'root\',\\\\r\\\\n  password \'sfdjfFF#s2332\',\\\\r\\\\n  driver \'com.mysql.cj.jdbc.Driver\'\\\\r\\\\n);\\\\r\\\\n\\\\r\\\\n-- ========== 3) 目标：Doris 报表（通过 MySQL 协议）==========\\\\r\\\\nCREATE TABLE IF NOT EXISTS dws_station_water_day_report_jdbc\\\\r\\\\nUSING jdbc\\\\r\\\\nOPTIONS (\\\\r\\\\n  url \'jdbc:mysql://host.docker.internal:9030/dws?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai\',\\\\r\\\\n  dbtable \'dws_station_water_day_report\',\\\\r\\\\n  user \'root\',\\\\r\\\\n  password \'InC3tmU4bijT4vkl\',\\\\r\\\\n  driver \'com.mysql.cj.jdbc.Driver\'\\\\r\\\\n);\\\\r\\\\n\\\\r\\\\n-- ========== 4) 计算“日平均水位”并写入目标 ==========\\\\r\\\\nWITH base AS (\\\\r\\\\n  SELECT\\\\r\\\\n    wl.station_code,\\\\r\\\\n    COALESCE(wl.obs_date, CAST(wl.obs_time AS DATE)) AS stat_date,\\\\r\\\\n    CAST(wl.water_level_m AS DOUBLE)                  AS water_level_m\\\\r\\\\n  FROM hyd_water_level_src wl\\\\r\\\\n  WHERE wl.water_level_m IS NOT NULL\\\\r\\\\n),\\\\r\\\\nday_avg AS (\\\\r\\\\n  SELECT\\\\r\\\\n    station_code,\\\\r\\\\n    stat_date,\\\\r\\\\n    AVG(water_level_m) AS avg_level_day\\\\r\\\\n  FROM base\\\\r\\\\n  GROUP BY station_code, stat_date\\\\r\\\\n)\\\\r\\\\n\\\\r\\\\nINSERT INTO dws_station_water_day_report_jdbc\\\\r\\\\nSELECT\\\\r\\\\n  -- station_id：有维表用维表，没有则置 NULL\\\\r\\\\n  COALESCE(CAST(s.station_id AS BIGINT), CAST(NULL AS BIGINT))             AS station_id,\\\\r\\\\n  -- station_name：有维表用维表名称，没有则用 station_code 顶上\\\\r\\\\n  COALESCE(CAST(s.station_name AS STRING), CAST(d.station_code AS STRING)) AS station_name,\\\\r\\\\n  -- 写入日平均（保留三位小数），沿用目标表列名 avg_level_year\\\\r\\\\n  CAST(ROUND(d.avg_level_day, 3) AS DECIMAL(10,3))                          AS avg_level_year,\\\\r\\\\n  CAST(d.stat_date AS DATE)                                                 AS stat_date\\\\r\\\\nFROM day_avg d\\\\r\\\\nLEFT JOIN hyd_station_dim s\\\\r\\\\n  ON s.station_code = d.station_code;\\\",\\\"resourceList\\\":[],\\\"programType\\\":\\\"JAVA\\\",\\\"mainClass\\\":\\\"tech.qiantong.qdata.spark.etl.EtlApplication\\\",\\\"deployMode\\\":\\\"client\\\",\\\"master\\\":\\\"spark://spark:7077\\\",\\\"sqlExecutionType\\\":\\\"SCRIPT\\\",\\\"driverCores\\\":1,\\\"driverMemory\\\":\\\"512M\\\",\\\"numExecutors\\\":1,\\\"executorMemory\\\":\\\"1G\\\",\\\"executorCores\\\":1,\\\"yarnQueue\\\":\\\"\\\"}\",\n  \"environmentConfig\" : \"export FLINK_HOME=/opt/soft/flink\\nexport SPARK_HOME=/opt/soft/spark\\nexport DATAX_LAUNCHER=/opt/soft/datax/bin/datax.py\\nexport PYTHON_LAUNCHER=/usr/bin/python3\\nexport JAVA_HOME=/opt/java/openjdk\\nexport PATH=$FLINK_HOME/bin:$SPARK_HOME/bin:$PYTHON_LAUNCHER:$JAVA_HOME/bin:$DATAX_LAUNCHER:$PATH\",\n  \"prepareParamsMap\" : {\n    \"system.task.definition.name\" : {\n      \"prop\" : \"system.task.definition.name\",\n      \"direct\" : \"IN\",\n      \"type\" : \"VARCHAR\",\n      \"value\" : \"SparkSQL_水位日统计报表\"\n    },\n    \"system.project.name\" : {\n      \"prop\" : \"system.project.name\",\n      \"direct\" : \"IN\",\n      \"type\" : \"VARCHAR\",\n      \"value\" : null\n    },\n    \"system.project.code\" : {\n      \"prop\" : \"system.project.code\",\n      \"direct\" : \"IN\",\n      \"type\" : \"VARCHAR\",\n      \"value\" : \"152317790975712\"\n    },\n    \"system.workflow.instance.id\" : {\n      \"prop\" : \"system.workflow.instance.id\",\n      \"direct\" : \"IN\",\n      \"type\" : \"VARCHAR\",\n      \"value\" : \"96\"\n    },\n    \"system.biz.curdate\" : {\n      \"prop\" : \"system.biz.curdate\",\n      \"direct\" : \"IN\",\n      \"type\" 