INSERT INTO `dpp_etl_node_instance_log` VALUES (66, '2025-09-22 15:07:15', '3', 45, '152659477902656', 66, '[INFO] 2025-09-22 15:07:05.902 -\n***********************************************************************************************[INFO] 2025-09-22 15:07:05.912 - *********************************  Initialize task context  ***********************************\n[INFO] 2025-09-22 15:07:05.914 - ***********************************************************************************************\n[INFO] 2025-09-22 15:07:05.916 - Begin to initialize task\n[INFO] 2025-09-22 15:07:05.918 - Set task startTime: 1758524825918\n[INFO] 2025-09-22 15:07:05.920 - Set task appId: 66_66\n[INFO] 2025-09-22 15:07:05.923 - End initialize task {\n  \"taskInstanceId\" : 66,\n  \"taskName\" : \"Flink流_水位信息采集\",\n  \"firstSubmitTime\" : 1758524825887,\n  \"startTime\" : 1758524825918,\n  \"taskType\" : \"FLINK\",\n  \"workflowInstanceHost\" : \"172.28.0.11:5678\",\n  \"host\" : \"172.28.0.17:1234\",\n  \"logPath\" : \"/opt/dolphinscheduler/logs/20250922/152659477902656/3/66/66.log\",\n  \"processId\" : 0,\n  \"processDefineCode\" : 152659477902656,\n  \"processDefineVersion\" : 3,\n  \"processInstanceId\" : 66,\n  \"scheduleTime\" : 0,\n  \"executorId\" : 1,\n  \"cmdTypeIfComplement\" : 0,\n  \"tenantCode\" : \"default\",\n  \"processDefineId\" : 0,\n  \"projectId\" : 0,\n  \"projectCode\" : 152317790975712,\n  \"taskParams\" : \"{\\\"localParams\\\":[],\\\"rawScript\\\":\\\"ADD JAR \'file:///opt/soft/flink/lib/flink-doris-connector-1.17-25.1.0.jar\';\\\\r\\\\n\\\\r\\\\n-- ========= 1) 源表：MySQL (hyd.hyd_water_level)  =========\\\\r\\\\nCREATE TABLE src_hyd_water_level (\\\\r\\\\n  id              BIGINT,              -- MySQL: bigint(20) unsigned AUTO_INCREMENT\\\\r\\\\n  station_code    STRING,\\\\r\\\\n  sensor_id       BIGINT,\\\\r\\\\n  obs_time        TIMESTAMP(3),        -- MySQL: datetime\\\\r\\\\n  obs_date        DATE,                -- MySQL: date\\\\r\\\\n  water_level_m   DECIMAL(10,3),\\\\r\\\\n  quality_code    STRING,\\\\r\\\\n  source          STRING,\\\\r\\\\n  trace_id        STRING,\\\\r\\\\n  ext_json        STRING,              -- MySQL: text -> 以 STRING 读取\\\\r\\\\n  created_at      TIMESTAMP(3),        -- MySQL: timestamp\\\\r\\\\n  PRIMARY KEY (id) NOT ENFORCED\\\\r\\\\n) WITH (\\\\r\\\\n  \'connector\' = \'mysql-cdc\',\\\\r\\\\n  \'hostname\'  = \'mysql57\',\\\\r\\\\n  \'port\'      = \'3306\',\\\\r\\\\n  \'username\'  = \'root\',\\\\r\\\\n  \'password\'  = \'sfdjfFF#s2332\',\\\\r\\\\n  \'database-name\' = \'hydrology\',\\\\r\\\\n  \'table-name\'    = \'hyd_water_level\',\\\\r\\\\n  -- 建议设置时区，避免时间字段偏移\\\\r\\\\n  \'server-time-zone\' = \'Asia/Shanghai\',\\\\r\\\\n  -- 开启增量快照，首跑更稳\\\\r\\\\n  \'scan.incremental.snapshot.enabled\' = \'true\'\\\\r\\\\n);\\\\r\\\\n\\\\r\\\\n-- ========= 2) 目标表：Doris (ods.ods_hyd_water_level_flink_stream) =========\\\\r\\\\n-- 说明：与你给的 Doris 目标表字段/顺序一致（id → created_at）\\\\r\\\\nCREATE TABLE sink_ods_hyd_water_level_flink_stream (\\\\r\\\\n  id             BIGINT         COMMENT \'自增主键\',\\\\r\\\\n  station_code   VARCHAR(64)    COMMENT \'站点编码（软关联）\',\\\\r\\\\n  sensor_id      BIGINT         COMMENT \'传感器ID（软关联）\',\\\\r\\\\n  obs_time       TIMESTAMP(3)   COMMENT \'观测时间\',          -- Doris: DATETIME，Flink 写入 TIMESTAMP(3) OK\\\\r\\\\n  obs_date       DATE           COMMENT \'观测日期\',\\\\r\\\\n  water_level_m  DECIMAL(10,3)  COMMENT \'水位(米)\',\\\\r\\\\n  quality_code   VARCHAR(16)    COMMENT \'质量代码\',\\\\r\\\\n  source         VARCHAR(64)    COMMENT \'来源\',\\\\r\\\\n  trace_id       VARCHAR(64)    COMMENT \'追踪ID/批次号\',\\\\r\\\\n  ext_json       STRING         COMMENT \'扩展字段（原 JSON）\', -- Doris TEXT 也可接收；用 STRING 写入最通用\\\\r\\\\n  created_at     TIMESTAMP(3)   COMMENT \'创建时间\'\\\\r\\\\n) WITH (\\\\r\\\\n  \'connector\' = \'doris\',\\\\r\\\\n  -- Doris FE http 端口（一般 8030）\\\\r\\\\n  \'fenodes\' = \'host.docker.internal:8030\',\\\\r\\\\n  -- JDBC URL（建议指向 9030）\\\\r\\\\n  \'jdbc-url\' = \'jdbc:mysql://host.