INSERT INTO `dpp_etl_node_instance_log` VALUES (62, '2025-09-22 14:44:06', '3', 43, '152659477902656', 62, '[INFO] 2025-09-22 14:44:00.130 -\n***********************************************************************************************[INFO] 2025-09-22 14:44:00.141 - *********************************  Initialize task context  ***********************************\n[INFO] 2025-09-22 14:44:00.142 - ***********************************************************************************************\n[INFO] 2025-09-22 14:44:00.144 - Begin to initialize task\n[INFO] 2025-09-22 14:44:00.145 - Set task startTime: 1758523440145\n[INFO] 2025-09-22 14:44:00.146 - Set task appId: 62_62\n[INFO] 2025-09-22 14:44:00.148 - End initialize task {\n  \"taskInstanceId\" : 62,\n  \"taskName\" : \"Flink流_水位信息采集\",\n  \"firstSubmitTime\" : 1758523440109,\n  \"startTime\" : 1758523440145,\n  \"taskType\" : \"FLINK\",\n  \"workflowInstanceHost\" : \"172.28.0.11:5678\",\n  \"host\" : \"172.28.0.17:1234\",\n  \"logPath\" : \"/opt/dolphinscheduler/logs/20250922/152659477902656/2/62/62.log\",\n  \"processId\" : 0,\n  \"processDefineCode\" : 152659477902656,\n  \"processDefineVersion\" : 2,\n  \"processInstanceId\" : 62,\n  \"scheduleTime\" : 0,\n  \"executorId\" : 1,\n  \"cmdTypeIfComplement\" : 0,\n  \"tenantCode\" : \"default\",\n  \"processDefineId\" : 0,\n  \"projectId\" : 0,\n  \"projectCode\" : 152317790975712,\n  \"taskParams\" : \"{\\\"localParams\\\":[],\\\"rawScript\\\":\\\"-- ========= 1) 源表：MySQL (hyd.hyd_water_level)  =========\\\\r\\\\nCREATE TABLE src_hyd_water_level (\\\\r\\\\n  id              BIGINT,              -- MySQL: bigint(20) unsigned AUTO_INCREMENT\\\\r\\\\n  station_code    STRING,\\\\r\\\\n  sensor_id       BIGINT,\\\\r\\\\n  obs_time        TIMESTAMP(3),        -- MySQL: datetime\\\\r\\\\n  obs_date        DATE,                -- MySQL: date\\\\r\\\\n  water_level_m   DECIMAL(10,3),\\\\r\\\\n  quality_code    STRING,\\\\r\\\\n  source          STRING,\\\\r\\\\n  trace_