INSERT INTO `dpp_etl_node_log` VALUES (78, '3', 'FLINK', 'Flink批_水位信息采集', '152660481929536', 10, 1, '152317790975712', '{\"taskPriority\":\"MEDIUM\",\"workerGroup\":\"default\",\"failRetryTimes\":0,\"failRetryInterval\":1,\"delayTime\":0,\"jobManagerMemory\":\"1G\",\"taskManagerMemory\":\"2G\",\"slot\":1,\"taskManager\":2,\"parallelism\":1,\"yarnQueue\":\"\",\"driverCores\":1,\"driverMemory\":\"512M\",\"numExecutors\":1,\"executorMemory\":\"1G\",\"executorCores\":1,\"typaCode\":\"FlinkBatch\",\"datasourceId\":\"\",\"sqlType\":\"0\",\"taskType\":\"FLINK\",\"segm\":\"\",\"componentType\":\"55\",\"localParams\":[],\"sql\":\"CREATE TABLE hyd_water_level_src (\\r\\n    id             BIGINT,\\r\\n    station_code   STRING,\\r\\n    sensor_id      BIGINT,\\r\\n    obs_time       TIMESTAMP(3),\\r\\n    obs_date       DATE,\\r\\n    water_level_m  DECIMAL(10,3),\\r\\n    quality_code   STRING,\\r\\n    source         STRING,\\r\\n    trace_id       STRING,\\r\\n    ext_json       STRING,\\r\\n    created_at     TIMESTAMP(3),\\r\\n    PRIMARY KEY (id) NOT ENFORCED\\r\\n) WITH (\\r\\n    \'connector\' = \'jdbc\',\\r\\n    \'url\'       = \'jdbc:mysql://mysql57:3306/hydrology?useSSL=false&serverTimezone=Asia/Shanghai\',\\r\\n    \'table-name\'= \'hyd_water_level\',\\r\\n    \'username\'  = \'root\',\\r\\n    \'password\'  = \'sfdjfFF#s2332\',\\r\\n    \'sink.buffer-flush.max-rows\' = \'500\',\\r\\n    \'sink.buffer-flush.interval\' = \'2s\',\\r\\n    \'sink.max-retries\' = \'3\'\\r\\n);\\r\\n\\r\\nCREATE TABLE hyd_water_level_sink (\\r\\n    id             BIGINT,\\r\\n    station_code   STRING,\\r\\n    sensor_id      BIGINT,\\r\\n    obs_time       TIMESTAMP(3),\\r\\n    obs_date       DATE,\\r\\n    water_level_m  DECIMAL(10,3),\\r\\n    quality_code   STRING,\\r\\n    source         STRING,\\r\\n    trace_id       STRING,\\r\\n    ext_json       STRING,\\r\\n    created_at     TIMESTAMP(3),\\r\\n    PRIMARY KEY (id) NOT ENFORCED\\r\\n) WITH (\\r\\n    \'connector\' = \'jdbc\',\\r\\n    \'url\'       = \'jdbc:mysql://mysql57:3306/hydrology?useSSL=false&serverTimezone=Asia/Shanghai\',\\r\\n    \'table-name\'= \'hyd_water_level_stream\',\\r\\n    \'username\'  = \'root\',\\r\\n    \'password\'  = \'sfdjfFF#s2332\',\\r\\n    \'sink.buffer-flush.max-rows\' = \'500\',\\r\\n    \'sink.buffer-flush.interval\' = \'2s\',\\r\\n    \'sink.max-retries\' = \'3\'\\r\\n);\\r\\n\\r\\nINSERT INTO hyd_water_level_sink\\r\\nSELECT\\r\\n    id\\r\\nFROM hyd_water_level_src;\",\"executeMode\":\"BATCH\"}', 'MEDIUM', 0, 1, 0, 0, -1, -1, '【离线同步 】Flink 批处理导入历史水位数据  ', 82, '1', '0', '吴同', 2, '2025-09-22 17:04:40', '吴同', 2, '2025-09-22 17:04:40', NULL, '55');
INSERT INTO `dpp_etl_node_log` VALUES (79, '3', 'SPARK', 'SparkSQL_水位日统计报表', '152667889198400', 3, 1, '152317790975712', '{\"taskPriority\":\"MEDIUM\",\"workerGroup\":\"default\",\"failRetryTimes\":0,\"failRetryInterval\":1,\"delayTime\":0,\"jobManagerMemory\":\"1G\",\"taskManagerMemory\":\"2G\",\"slot\":1,\"taskManager\":2,\"parallelism\":1,\"yarnQueue\":\"\",\"driverCores\":1,\"driverMemory\":\"512M\",\"numExecutors\":1,\"executorMemory\":\"1G\",\"executorCores\":1,\"typaCode\":\"SparkSql\",\"datasourceId\":\"\",\"sqlType\":\"0\",\"taskType\":\"SPARK\",\"segm\":\"\",\"componentType\":\"53\",\"localParams\":[],\"sql\":\"-- ========== 1) 源：MySQL 水位明细 ==========\\r\\nCREATE TEMPORARY VIEW hyd_water_level_src\\r\\nUSING jdbc\\r\\nOPTIONS (\\r\\n  url \'jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai\',\\r\\n  dbtable \'hyd_water_level\',\\r\\n  user \'root\',\\r\\n  password \'sfdjfFF#s2332\',\\r\\n  driver \'com.mysql.cj.jdbc.Driver\'\\r\\n);\\r\\n\\r\\n-- ========== 2) 可选维度：站点表（如没有可保留，后续会自动降级为用 station_code 代替名称）==========\\r\\n-- 期望列：station_id BIGINT, station_code VARCHAR, station_name VARCHAR\\r\\nCREATE TEMPORARY VIEW hyd_station_dim\\r\\nUSING jdbc\\r\\nOPTIONS (\\r\\n  url \'jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai\',\\r\\n  dbtable \'hyd_station\',                       -- 没有就保持这样；后续 LEFT JOIN + COALESCE 兼容\\r\\n  user \'root\',\\r\\n  password \'sfdjfFF#s2332\',\\r\\n  driver \'com.mysql.cj.jdbc.Driver\'\\r\\n);\\r\\n\\r\\n-- ========== 3) 目标：Doris 报表（通过 MySQL 协议）==========\\r\\nCREATE TABLE IF NOT EXISTS dws_station_water_day_report_jdbc\\r\\nUSING jdbc\\r\\nOPTIONS (\\r\\n  url \'jdbc:mysql://host.docker.internal:9030/dws?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai\',\\r\\n  dbtable \'dws_station_water_day_report\',\\r\\n  user \'root\',\\r\\n  password \'InC3tmU4bijT4vkl\',\\r\\n  driver \'com.mysql.cj.jdbc.Driver\'\\r\\n);\\r\\n\\r\\n-- ========== 4) 计算“日平均水位”并写入目标 ==========\\r\\nWITH base AS (\\r\\n  SELECT\\r\\n    wl.station_code,\\r\\n    COALESCE(wl.obs_date, CAST(wl.obs_time AS DATE)) AS stat_date,\\r\\n    CAST(wl.water_level_m AS DOUBLE)                  AS water_level_m\\r\\n  FROM hyd_water_level_src wl\\r\\n  WHERE wl.water_level_m IS NOT NULL\\r\\n),\\r\\nday_avg AS (\\r\\n  SELECT\\r\\n    station_code,\\r\\n    stat_date,\\r\\n    AVG(water_level_m) AS avg_level_day\\r\\n  FROM base\\r\\n  GROUP BY station_code, stat_date\\r\\n)\\r\\n\\r\\nINSERT INTO dws_station_water_day_report_jdbc\\r\\nSELECT\\r\\n  -- station_id：有维表用维表，没有则置 NULL\\r\\n  COALESCE(CAST(s.station_id AS BIGINT), CAST(NULL AS BIGINT))             AS station_id,\\r\\n  -- station_name：有维表用维表名称，没有则用 station_code 顶上\\r\\n  COALESCE(CAST(s.station_name AS STRING), CAST(d.station_code AS STRING)) AS station_name,\\r\\n  -- 写入日平均（保留三位小数），沿用目标表列名 avg_level_year\\r\\n  CAST(ROUND(d.avg_level_day, 3) AS DECIMAL(10,3))                          AS avg_level_year,\\r\\n  CAST(d.stat_date AS DATE)                                                 AS stat_date\\r\\nFROM day_avg d\\r\\nLEFT JOIN hyd_station_dim s\\r\\n  ON s.station_code = d.station_code;\",\"executeMode\":\"\"}', 'MEDIUM', 0, 1, 0, 0, -1, -1, '【MySQL → 达梦】查询水位实时数据，生成每日统计报表', 85, '1', '0', '吴同', 2, '2025-09-22 17:18:24', '吴同', 2, '2025-09-22 17:18:24', NULL, '53');
INSERT INTO `dpp_etl_node_log` VALUES (80, '3', 'FLINK', 'Flink流_水位信息采集', '152659477902656', 26, 1, '152317790975712', '{\"taskPriority\":\"MEDIUM\",\"workerGroup\":\"default\",\"failRetryTimes\":0,\"failRetryInterval\":1,\"delayTime\":0,\"jobManagerMemory\":\"1G\",\"taskManagerMemory\":\"2G\",\"slot\":1,\"taskManager\":2,\"parallelism\":1,\"yarnQueue\":\"\",\"driverCores\":1,\"driverMemory\":\"512M\",\"numExecutors\":1,\"executorMemory\":\"1G\",\"executorCores\":1,\"typaCode\":\"FlinkStream\",\"datasourceId\":\"\",\"sqlType\":\"0\",\"taskType\":\"FLINK\",\"segm\":\"\",\"componentType\":\"55\",\"localParams\":[],\"sql\":\"CREATE TABLE hyd_water_level_src (\\r\\n    id             BIGINT,\\r\\n    station_code   STRING,\\r\\n    sensor_id      BIGINT,\\r\\n    obs_time       TIMESTAMP(3),\\r\\n    obs_date       DATE,\\r\\n    water_level_m  DECIMAL(10,3),\\r\\n    quality_code   STRING,\\r\\n    source         STRING,\\r\\n    trace_id       STRING,\\r\\n    ext_json       STRING,\\r\\n    created_at     TIMESTAMP(3),\\r\\n    PRIMARY KEY (id) NOT ENFORCED\\r\\n) WITH (\\r\\n    \'connector\' = \'mysql-cdc\',\\r\\n    \'hostname\'  = \'mysql57\',\\r\\n    \'port\'      = \'3306\',\\r\\n    \'username\'  = \'root\',\\r\\n    \'password\'  = \'sfdjfFF#s2332\',\\r\\n    \'server-time-zone\' = \'Asia/Shanghai\',\\r\\n    \'scan.incremental.snapshot.enabled\' = \'true\',\\r\\n    \'debezium.snapshot.mode\' = \'latest-offset\',\\r\\n    \'database-name\' = \'hydrology\',\\r\\n    \'table-name\'    = \'hyd_water_level\'\\r\\n);\\r\\n\\r\\nCREATE TABLE hyd_water_level_sink (\\r\\n    id             BIGINT,\\r\\n    station_code   STRING,\\r\\n    sensor_id      BIGINT,\\r\\n    obs_time       TIMESTAMP(3),\\r\\n    obs_date       DATE,\\r\\n    water_level_m  DECIMAL(10,3),\\r\\n    quality_code   STRING,\\r\\n    source         STRING,\\r\\n    trace_id       STRING,\\r\\n    ext_json       STRING,\\r\\n    created_at     TIMESTAMP(3),\\r\\n    PRIMARY KEY (id) NOT ENFORCED\\r\\n) WITH (\\r\\n    \'connector\' = \'jdbc\',\\r\\n    \'url\'       = \'jdbc:mysql://mysql57:3306/hydrology?useSSL=false&serverTimezone=Asia/Shanghai\',\\r\\n    \'table-name\'= \'hyd_water_level_stream\',\\r\\n    \'username\'  = \'root\',\\r\\n    \'password\'  = \'sfdjfFF#s2332\',\\r\\n    \'sink.buffer-flush.max-rows\' = \'500\',\\r\\n    \'sink.buffer-flush.interval\' = \'2s\',\\r\\n    \'sink.max-retries\' = \'3\'\\r\\n);\\r\\n\\r\\nINSERT INTO hyd_water_level_sink\\r\\nSELECT\\r\\n    id,\\r\\n    station_code,\\r\\n    sensor_id,\\r\\n    CAST(obs_time AS TIMESTAMP(3)) AS obs_time,\\r\\n    obs_date,\\r\\n    water_level_m,\\r\\n    COALESCE(quality_code, \'OK\') AS quality_code,\\r\\n    source,\\r\\n    trace_id,\\r\\n    ext_json,\\r\\n    CAST(created_at AS TIMESTAMP(3)) AS created_at\\r\\nFROM hyd_water_level_src;\",\"executeMode\":\"STREAM\"}', 'MEDIUM', 0, 1, 0, 0, -1, -1, '【实时同步，毫秒级延迟】Flink 流处理导入历史水位数据  ', 81, '1', '0', '吴同', 2, '2025-09-22 17:25:01', '吴同', 2, '2025-09-22 17:25:01', NULL, '55');
