INSERT INTO `ds_api` VALUES (4, 3, 'A01A01', '流域水位查询服务', 'v1.1.0', '/api/water/level/river/list', '2', '2', '3', NULL, '{\"apiServiceType\":\"2\",\"reqParams\":[],\"resParams\":[{\"fieldId\":null,\"fieldName\":\"obs_time\",\"fieldComment\":\"观测时间\",\"dataType\":\"datetime\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"obs_date\",\"fieldComment\":\"观测日期\",\"dataType\":\"date\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"water_level_m\",\"fieldComment\":\"水位(米)\",\"dataType\":\"decimal\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"station_id\",\"fieldComment\":\"站点主键\",\"dataType\":\"bigint\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"station_code\",\"fieldComment\":\"站点编码（第三方库唯一）\",\"dataType\":\"varchar\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"station_name\",\"fieldComment\":\"站点名称\",\"dataType\":\"varchar\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"station_type\",\"fieldComment\":\"站点类型\",\"dataType\":\"enum\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"basin_code\",\"fieldComment\":\"流域编码\",\"dataType\":\"varchar\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"river_name\",\"fieldComment\":\"河流名称\",\"dataType\":\"varchar\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null}],\"headerJson\":[],\"table\":{},\"transmitType\":\"\",\"apiId\":\"\",\"categoryAssetList\":\"\",\"sqlText\":\"SELECT\\n    s.station_id,\\n    s.station_code,\\n    s.station_name,\\n    s.station_type,\\n    s.basin_code,\\n    s.river_name,\\n    w.obs_time,\\n    w.obs_date,\\n    w.water_level_m\\nFROM hydrology.hyd_station s\\nJOIN hydrology.hyd_water_level w\\n    ON s.station_code = w.station_code\\nORDER BY s.basin_code, s.station_code, w.obs_time\",\"sourceId\":11,\"filteredTableOptions\":[{\"tableName\":\"hyd_discharge\",\"tableComment\":\"流量时序数据\"},{\"tableName\":\"hyd_quality_code\",\"tableComment\":\"监测数据质量代码字典\"},{\"tableName\":\"hyd_rainfall\",\"tableComment\":\"降雨量时序数据\"},{\"tableName\":\"hyd_sensor\",\"tableComment\":\"传感器/数据源\"},{\"tableName\":\"hyd_station\",\"tableComment\":\"水文站点基础信息\"},{\"tableName\":\"hyd_water_level\",\"tableComment\":\"水位时序数据\"}],\"lastSqlText\":\"SELECT\\n    s.station_id,\\n    s.station_code,\\n    s.station_name,\\n    s.station_type,\\n    s.basin_code,\\n    s.river_name,\\n    w.obs_time,\\n    w.obs_date,\\n    w.water_level_m\\nFROM hydrology.hyd_station s\\nJOIN hydrology.hyd_water_level w\\n    ON s.station_code = w.station_code\\nORDER BY s.basin_code, s.station_code, w.obs_time\"}', NULL, '[]', '[{\"fieldId\":null,\"fieldName\":\"obs_time\",\"fieldComment\":\"观测时间\",\"dataType\":\"datetime\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"obs_date\",\"fieldComment\":\"观测日期\",\"dataType\":\"date\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"water_level_m\",\"fieldComment\":\"水位(米)\",\"dataType\":\"decimal\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"station_id\",\"fieldComment\":\"站点主键\",\"dataType\":\"bigint\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"station_code\",\"fieldComment\":\"站点编码（第三方库唯一）\",\"dataType\":\"varchar\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"station_name\",\"fieldComment\":\"站点名称\",\"dataType\":\"varchar\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"station_type\",\"fieldComment\":\"站点类型\",\"dataType\":\"enum\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"basin_code\",\"fieldComment\":\"流域编码\",\"dataType\":\"varchar\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null},{\"fieldId\":null,\"fieldName\":\"river_name\",\"fieldComment\":\"河流名称\",\"dataType\":\"varchar\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null}]', '【SQL脚本式-多表关联，分页】查询流域、站点、水位的实时信息数据。', '1', '1', '1', '吴同', 2, '2025-09-22 14:37:19', 'wutong', 2, '2025-09-22 15:12:01', NULL, NULL, NULL, '[]');
INSERT INTO `ds_api` VALUES (5, 3, 'A01A01', '水文监测水位日报查询服务', 'v2.1.1', '/api/water/level/station/daily/list', '2', '2', '3', NULL, '{\"apiServiceType\":\"2\",\"reqParams\":[],\"resParams\":[{\"fieldId\":null,\"fieldName\":\"station_code\",\"fieldComment\":\"站点编码（软关联）\",\"dataType\":\"varchar\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null}],\"headerJson\":[],\"table\":{},\"transmitType\":\"\",\"apiId\":\"\",\"categoryAssetList\":\"\",\"sqlText\":\"SELECT\\n    station_code,\\n    DATE(obs_date) AS stat_date,\\n    AVG(water_level_m) AS avg_water_level\\nFROM hydrology.hyd_water_level\\nGROUP BY station_code, DATE(obs_date)\\nORDER BY station_code, stat_date\",\"sourceId\":11,\"filteredTableOptions\":[{\"tableName\":\"hyd_discharge\",\"tableComment\":\"流量时序数据\"},{\"tableName\":\"hyd_quality_code\",\"tableComment\":\"监测数据质量代码字典\"},{\"tableName\":\"hyd_rainfall\",\"tableComment\":\"降雨量时序数据\"},{\"tableName\":\"hyd_sensor\",\"tableComment\":\"传感器/数据源\"},{\"tableName\":\"hyd_station\",\"tableComment\":\"水文站点基础信息\"},{\"tableName\":\"hyd_water_level\",\"tableComment\":\"水位时序数据\"}],\"lastSqlText\":\"SELECT\\n    station_code,\\n    DATE(obs_date) AS stat_date,\\n    AVG(water_level_m) AS avg_water_level\\nFROM hydrology.hyd_water_level\\nGROUP BY station_code, DATE(obs_date)\\nORDER BY station_code, stat_date\"}', NULL, '[]', '[{\"fieldId\":null,\"fieldName\":\"station_code\",\"fieldComment\":\"站点编码（软关联）\",\"dataType\":\"varchar\",\"exampleValue\":null,\"fieldAliasName\":\"\",\"resParamList\":null}]', '【SQL脚本式，分页】按日期/站点筛选日均/日报指标，支持排序与分页，用于日报看板与综合统计。', '1', '1', '1', '吴同', 2, '2025-09-22 14:38:52', 'wutong', 2, '2025-09-22 15:12:03', NULL, NULL, NULL, '[]');
