INSERT INTO `onl_drag_dataset_head` VALUES ('1516743766914924546', '统计近十日的登陆次数', NULL, '1516743332632494082', '1011872166805864448', 'SELECT\n  count(*) num,\n DATE_FORMAT(create_time, \'%Y-%m-%d\') AS `day`\nFROM\n sys_log\nWHERE\n  log_type = 1\nAND create_time > DATE_SUB(NOW(), INTERVAL 10 DAY)\nGROUP BY\n  DATE_FORMAT(create_time, \'%Y-%m-%d\')', NULL, NULL, 'sql', 'get', '2022-04-20 19:41:08', '吴同', '2024-10-31 15:51:02', '吴同', NULL, 1);
